def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set(); objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); pts = []
            while stack:
                a, b = stack.pop(); pts.append((a, b))
                for x, y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0 <= x < h and 0 <= y < w and grid[x][y] == color and (x,y) not in seen:
                        seen.add((x,y)); stack.append((x,y))
            objects.append((color, pts))
    by_color = {}
    for color, pts in objects:
        by_color.setdefault(color, []).append(pts)
    colors = sorted(by_color, key=lambda col: min(min(c for r,c in p) for p in by_color[col]))
    out = [[0] * w for _ in range(h)]
    for lane, color in enumerate(colors[:2]):
        shapes = sorted(by_color[color], key=len)
        left = 0 if lane == 0 else 5
        for idx, pts in enumerate(shapes[:2]):
            r0 = min(r for r,c in pts); r1 = max(r for r,c in pts); c0 = min(c for r,c in pts)
            bottom = 5 if idx == 0 else 9
            for r,c in pts:
                rr = bottom - (r1-r); cc = left + (c-c0)
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    return out
